<?php
declare(strict_types=1);

$usage = "usage: ci-mftf-select.php <generated-dir> <msi-core checkout> <shard> <shards> [--tests a,b] [--group name]\n";
$arguments = array_slice($argv, 1);
$positional = [];
$options = ['--tests' => null, '--group' => null];
while ($arguments) {
    $argument = array_shift($arguments);
    if (array_key_exists($argument, $options)) {
        $options[$argument] = array_shift($arguments);
    } else {
        $positional[] = $argument;
    }
}
if (count($positional) !== 4 || !ctype_digit($positional[2]) || !ctype_digit($positional[3])) {
    fwrite(STDERR, $usage);
    exit(2);
}
[$generatedDir, $sourceDir, $shard, $shards] = $positional;
$shard = (int) $shard;
$shards = (int) $shards;
if ($shard < 1 || $shard > $shards) {
    fwrite(STDERR, "shard $shard is outside 1..$shards\n");
    exit(2);
}

$declared = [];
foreach (glob(rtrim($sourceDir, '/') . '/*/Test/Mftf/Test/*.xml') as $file) {
    $module = basename(dirname($file, 4));
    $xml = simplexml_load_file($file);
    foreach ($xml->test as $test) {
        $groups = [];
        foreach ($test->annotations->group ?? [] as $group) {
            $groups[] = (string) $group['value'];
        }
        $declared[(string) $test['name']] = ['module' => $module, 'groups' => $groups];
    }
}

$units = [];
foreach (glob(rtrim($generatedDir, '/') . '/*/*Cest.php') as $file) {
    $name = substr(basename($file), 0, -strlen('Cest.php'));
    if (isset($declared[$name])) {
        $units[] = ['name' => $name, 'container' => basename(dirname($file)), 'module' => $declared[$name]['module']];
    }
}

if ($options['--tests'] !== null) {
    $requested = array_values(array_filter(array_map('trim', explode(',', $options['--tests']))));
    $generated = array_column($units, 'name');
    $unknown = array_diff($requested, $generated);
    if ($unknown) {
        fwrite(STDERR, 'not generated by MFTF from a msi-core test: ' . implode(', ', $unknown) . "\n");
        exit(1);
    }
    $units = array_filter($units, static fn (array $unit): bool => in_array($unit['name'], $requested, true));
}
if ($options['--group'] !== null) {
    $units = array_filter(
        $units,
        static fn (array $unit): bool => in_array($options['--group'], $declared[$unit['name']]['groups'], true)
    );
}

usort($units, static fn (array $a, array $b): int => [$a['module'], $a['name'], $a['container']] <=> [$b['module'], $b['name'], $b['container']]);

$names = [];
foreach (array_values($units) as $index => $unit) {
    if ($index % $shards === $shard - 1) {
        $names[] = $unit['container'] === 'default' ? $unit['name'] : $unit['container'] . ':' . $unit['name'];
    }
}
usort($names, static fn (string $a, string $b): int => [str_contains($a, ':'), $a] <=> [str_contains($b, ':'), $b]);

echo implode('', array_map(static fn (string $name): string => $name . "\n", $names));
